/** One manually generated summary, identified by its DSH turn number. */
export interface TurnSummaryRecord {
  readonly turn: number
  readonly markdown: string
}

/** The persisted TSP document for one Session. */
export interface SessionSummaryDocument {
  readonly sessionId: string
  readonly sessionSummary: string
  readonly turnSummaries: readonly TurnSummaryRecord[]
}

/** The current completed turn rendered from its original events. */
export interface TurnSummaryInput {
  readonly turn: number
  readonly sourceMarkdown: string
}

/** Both summaries generated by one auxiliary request. */
export interface SummaryModelOutput {
  readonly turnSummary: string
  readonly sessionSummary: string
}
